<?php
declare(strict_types=1);
if (!isset($wams) || !is_array($wams) || empty($wams['authorized'])) {http_response_code(403);exit('WAMS authorization required.');}
$config=$wams['config'];
function csvh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function remoteCsv(array $c):array{
 $url=(string)($c['remoteUrl']??'');$timeout=max(2,min(60,(int)($c['timeoutSeconds']??20)));
 if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true))throw new RuntimeException('Ungültige Remote-CSV-URL.');
 $headers="Accept: text/csv,text/plain;q=0.9,*/*;q=0.1\r\nUser-Agent: WAMS-CSV-Reporting/1.0\r\n";$method=(string)($c['httpMethod']??'GET');$opts=['http'=>['method'=>$method,'timeout'=>$timeout,'ignore_errors'=>true,'header'=>$headers]];
 if($method==='POST'){$opts['http']['header'].="Content-Type: application/x-www-form-urlencoded\r\n";$opts['http']['content']=http_build_query([(string)($c['postField']??'downloadBtn')=>(string)($c['postValue']??'1')]);}
 $data=@file_get_contents($url,false,stream_context_create($opts));$status=0;foreach($http_response_header??[] as $line)if(preg_match('~^HTTP/\S+\s+(\d{3})~',$line,$m))$status=(int)$m[1];
 if($data===false)throw new RuntimeException('Remote-Daten sind nicht erreichbar. Möglicherweise wird der Host durch DNS blockiert. Versuche, sofern beim Remote-System zulässig, statt des Hostnamens die IP-Adresse.');
 if($status<200||$status>=300)throw new RuntimeException('Remote-System antwortet mit HTTP '.$status.'.');if($data==='')throw new RuntimeException('Das Remote-System liefert eine leere Antwort.');return [$data,$status];
}
$error='';$rows=[];$cols=[];
try{[$raw]=remoteCsv($config);$fh=fopen('php://temp','r+');fwrite($fh,$raw);rewind($fh);$delimiter=($config['delimiter']??',')==='\\t'?"\t":(string)($config['delimiter']??',');while(($r=fgetcsv($fh,0,$delimiter))!==false)$rows[]=$r;fclose($fh);if(($config['hasHeader']??true)&&$rows)$cols=array_map('trim',array_shift($rows));if(!$cols){$max=0;foreach($rows as $r)$max=max($max,count($r));for($i=1;$i<=$max;$i++)$cols[]='Spalte '.$i;}}catch(Throwable $e){$error=$e->getMessage();}
$title=(string)($config['title']??'CSV Reporting');$heading=(string)($config['heading']??$title);$refresh=max(0,(int)($config['refreshSeconds']??0));
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=csvh($title)?></title><?php if($refresh>0):?><meta http-equiv="refresh" content="<?=csvh($refresh)?>"><?php endif?><link rel="stylesheet" href="<?=csvh($wams['styleUrl'])?>"></head><body><main class="csv-app"><div class="csv-shell"><header class="csv-head"><div><h1><?=csvh($heading)?></h1><div class="csv-meta">Live-Ansicht, Daten werden nicht lokal gespeichert.</div></div><?php if(!empty($wams['canManage'])):?><a class="csv-manage" href="<?=csvh($wams['manageUrl'])?>">App verwalten</a><?php endif?></header><?php if($error):?><div class="csv-error"><?=csvh($error)?></div><?php else:?><section class="csv-card"><div class="csv-tools"><input type="search" data-csv-filter placeholder="Tabelle filtern"><span class="csv-meta"><span data-csv-count><?=count($rows)?></span> Zeilen</span></div><div class="csv-table-wrap"><table class="csv-table"><thead><tr><?php foreach($cols as $c):?><th><?=csvh($c)?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr data-csv-row><?php foreach($cols as $i=>$unused):?><td><?=csvh($r[$i]??'')?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></section><?php endif?></div></main><script src="<?=csvh($wams['scriptUrl'])?>"></script></body></html>
